struct WorkerConfig {
    pub max_retries: u32,
    pub timeout_ms: u64,
}

template <typename T>
size_t binary_search(const T* arr, size_t n, T target) {
    size_t low = 0, high = n;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (arr[mid] < target) low = mid + 1;
        else high = mid;
    }
    return low;
}
